function circuitSvgUrl(c) {
  const folder = c.type === 'minimal' ? 'minimal' : 'detailed';
  // F1-oriented SVGs give a more consistent visual orientation when available.
  return `https://raw.githubusercontent.com/julesr0y/f1-circuits-svg/main/circuits/${folder}/black-outline/${c.svg}`;
}

function tiBase(year) {
  return Number(year) === 2025
    ? 'https://raw.githubusercontent.com/TracingInsights-Archive/2025/main'
    : 'https://raw.githubusercontent.com/TracingInsights/2026/main';
}

function tiUrl(source, ...parts) {
  const event = source.event;
  return tiBase(source.year) + '/' +
    [event, ...parts].map(p => encodeURIComponent(String(p))).join('/');
}

