// RacingNews365, 2026 table, accessed 2026-09-12. Published indicative measurements.
const DRIVER_MEASUREMENTS={albon:[186,74],ocon:[186,66],russell:[185,70],bearman:[184,68],bortoleto:[184,71],hulkenberg:[184,78],stroll:[182,70],verstappen:[181,72],leclerc:[180,69],piastri:[178,68],sainz:[178,64],gasly:[177,70],colapinto:[174,71],hamilton:[174,73],lawson:[174,72],bottas:[173,69],lindblad:[173,68],perez:[173,63],antonelli:[172,70],alonso:[171,68],norris:[170,68],hadjar:[167,65]};
