/* modern-era-quiz.js */
const MODERN_ERA_QUIZ=[{"year":2016,"driver":"Nico Rosberg","driverPoints":385,"constructor":"Mercedes"},{"year":2017,"driver":"Lewis Hamilton","driverPoints":363,"constructor":"Mercedes"},{"year":2018,"driver":"Lewis Hamilton","driverPoints":408,"constructor":"Mercedes"},{"year":2019,"driver":"Lewis Hamilton","driverPoints":413,"constructor":"Mercedes"},{"year":2020,"driver":"Lewis Hamilton","driverPoints":347,"constructor":"Mercedes"},{"year":2021,"driver":"Max Verstappen","driverPoints":395.5,"constructor":"Mercedes"},{"year":2022,"driver":"Max Verstappen","driverPoints":454,"constructor":"Red Bull"},{"year":2023,"driver":"Max Verstappen","driverPoints":575,"constructor":"Red Bull"},{"year":2024,"driver":"Max Verstappen","driverPoints":437,"constructor":"McLaren"},{"year":2025,"driver":"Lando Norris","driverPoints":423,"constructor":"McLaren"}];

;
/* quiz.js */
/* Challenge V17 — trois périmètres documentaires réellement distincts. */
const QUIZ_LEVELS={
 amateur:{label:'Amateur',choices:3,description:'Saison moderne · de 2016 à 2026',categories:['Saison moderne','Pilotes','Circuits','Écuries']},
 expert:{label:'Expert',choices:3,description:'Toute l’histoire · hors écuries anciennes',categories:['Pilotes','Circuits','Écuries','Légendes']},
 pro:{label:'Pro',choices:4,description:'Toute l’histoire · toutes les catégories',categories:['Pilotes','Circuits','Écuries','Légendes','Écuries anciennes']}
};

function quizNumericOptions(value,mode='generic'){
 const v=Number(value),step=mode==='year'?1:(v>=100?10:v>=30?5:v>=10?2:1),values=[v];
 for(const delta of [-step,step,-step*2,step*2,-1,1,3,-3,4,5,10,-10]){
  const candidate=v+delta;if(candidate>=0&&!values.includes(candidate))values.push(candidate);if(values.length===5)break;
 }
 return values.map(String);
}
function quizNameOptions(correct,pool){
 const values=[...new Set(pool.map(String))].filter(value=>value!==String(correct));
 for(let i=values.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[values[i],values[j]]=[values[j],values[i]];}
 return [String(correct),...values.slice(0,4)];
}

function buildQuizPool(){
 const all=[];
 const add=(level,question,correct,options,category,explanation,meta={})=>{
  const clean=[...new Set(options.map(String))],answer=clean.indexOf(String(correct));
  if(answer<0||clean.length<QUIZ_LEVELS[level].choices)return;
  all.push({id:`${level}-${all.length}`,level,q:question,options:clean,answer,category,explanation,...meta});
 };
 const countries=[...new Set([...DRIVERS_2026,...LEGENDS_F1].map(driver=>driver.country))];
 const teamNames=TEAMS_2026.map(team=>team.name),teamCountries=TEAMS_2026.map(team=>team.country),powerUnits=TEAMS_2026.map(team=>team.powerUnit);
 const circuitCountries=CIRCUITS_2026.map(circuit=>circuit.country),events=Object.values(CAREER_DATA.events),eventNames=[...new Set(events.map(event=>event.raceName))];
 const historicTeams=typeof HISTORIC_TEAMS==='undefined'?[]:HISTORIC_TEAMS.teams;
 const historicCountries=historicTeams.map(team=>team.country),historicFirstYears=historicTeams.map(team=>team.firstYear);

 /* AMATEUR — titres 2016–2025 et faits de la grille et du calendrier 2026. */
 const modernDrivers=MODERN_ERA_QUIZ.map(season=>season.driver),modernConstructors=MODERN_ERA_QUIZ.map(season=>season.constructor),modernPoints=MODERN_ERA_QUIZ.map(season=>season.driverPoints);
 MODERN_ERA_QUIZ.forEach(season=>add('amateur',`Qui a été champion du monde des pilotes en ${season.year} ?`,season.driver,quizNameOptions(season.driver,modernDrivers),'Saison moderne',`${season.driver} a remporté le championnat du monde des pilotes ${season.year}.`,{periodStart:season.year,periodEnd:season.year}));
 MODERN_ERA_QUIZ.forEach(season=>add('amateur',`Quelle écurie a remporté le championnat constructeurs en ${season.year} ?`,season.constructor,quizNameOptions(season.constructor,[...modernConstructors,...teamNames]),'Saison moderne',`${season.constructor} a remporté le championnat constructeurs ${season.year}.`,{periodStart:season.year,periodEnd:season.year}));
 MODERN_ERA_QUIZ.forEach(season=>add('amateur',`Combien de points le champion du monde ${season.driver} a-t-il marqué en ${season.year} ?`,season.driverPoints,quizNameOptions(season.driverPoints,modernPoints),'Saison moderne',`${season.driver} a été champion ${season.year} avec ${season.driverPoints} points.`,{periodStart:season.year,periodEnd:season.year}));
 DRIVERS_2026.forEach(driver=>{
  const name=`${driver.first} ${driver.last}`;
  add('amateur',`Pour quelle écurie ${name} court-il en 2026 ?`,driver.team,quizNameOptions(driver.team,teamNames),'Pilotes',`${name} pilote pour ${driver.team} en 2026.`,{periodStart:2026,periodEnd:2026});
  add('amateur',`Quel numéro porte ${name} en 2026 ?`,driver.number,quizNameOptions(driver.number,DRIVERS_2026.map(item=>item.number)),'Pilotes',`${name} porte le numéro ${driver.number} en 2026.`,{periodStart:2026,periodEnd:2026});
  add('amateur',`Quelle est la nationalité sportive de ${name} sur la grille 2026 ?`,driver.country,quizNameOptions(driver.country,countries),'Pilotes',`${name} représente : ${driver.country}.`,{periodStart:2026,periodEnd:2026});
 });
 CIRCUITS_2026.forEach(circuit=>{
  add('amateur',`Dans quel pays se trouve le circuit de ${circuit.city}, présent au calendrier 2026 ?`,circuit.country,quizNameOptions(circuit.country,circuitCountries),'Circuits',`${circuit.name} se trouve en ${circuit.country}.`,{periodStart:2026,periodEnd:2026});
  add('amateur',`Quelle ville accueille ${circuit.name} au calendrier 2026 ?`,circuit.city,quizNameOptions(circuit.city,CIRCUITS_2026.map(item=>item.city)),'Circuits',`${circuit.name} est associé à ${circuit.city}.`,{periodStart:2026,periodEnd:2026});
 });
 TEAMS_2026.forEach(team=>{
  add('amateur',`À quel pays l’écurie ${team.name} est-elle rattachée en 2026 ?`,team.country,quizNameOptions(team.country,teamCountries),'Écuries',`${team.name} est rattachée à : ${team.country}.`,{periodStart:2026,periodEnd:2026});
  add('amateur',`Quel moteur utilise ${team.name} en 2026 ?`,team.powerUnit,quizNameOptions(team.powerUnit,powerUnits),'Écuries',`${team.name} utilise le moteur ${team.powerUnit} en 2026.`,{periodStart:2026,periodEnd:2026});
  const driver=DRIVERS_2026.find(item=>(team.drivers||[]).includes(item.id));
  if(driver)add('amateur',`Lequel de ces pilotes court pour ${team.name} en 2026 ?`,`${driver.first} ${driver.last}`,quizNameOptions(`${driver.first} ${driver.last}`,DRIVERS_2026.map(item=>`${item.first} ${item.last}`)),'Écuries',`${driver.first} ${driver.last} court pour ${team.name} en 2026.`,{periodStart:2026,periodEnd:2026});
 });

 /* EXPERT — toute la chronologie F1, sans les constructeurs historiques. */
 DRIVERS_2026.forEach(driver=>{
  const name=`${driver.first} ${driver.last}`,history=CAREER_DATA.drivers[driver.jolpicaId];
  add('expert',`Combien de victoires en Grand Prix ${name} a-t-il remportées ?`,driver.wins,quizNumericOptions(driver.wins),'Pilotes',`${name} : ${driver.wins} victoire(s) en Grand Prix, hors sprints.`,{fullHistory:true});
  add('expert',`Combien de pole positions en Grand Prix ${name} a-t-il obtenues ?`,driver.poles,quizNumericOptions(driver.poles),'Pilotes',`${name} : ${driver.poles} pole position(s) en Grand Prix.`,{fullHistory:true});
  if(history.wins.length){const first=CAREER_DATA.events[history.wins.at(-1)];add('expert',`À quel Grand Prix ${name} a-t-il remporté sa première victoire ?`,first.raceName,quizNameOptions(first.raceName,eventNames),'Pilotes',`${first.raceName} ${first.season}, à ${first.locality}.`,{fullHistory:true});}
 });
 CIRCUITS_2026.forEach(circuit=>{
  add('expert',circuit.id==='madrid'?`En quelle année le premier Grand Prix de F1 à Madrid est-il programmé ?`:`En quelle année ${circuit.name} a-t-il accueilli son premier Grand Prix de F1 ?`,circuit.stats.firstGp,quizNumericOptions(circuit.stats.firstGp,'year'),'Circuits',`Premier Grand Prix du championnat du monde sur ce circuit : ${circuit.stats.firstGp}.`,{fullHistory:true});
  add('expert',`Quelle est la longueur de ${circuit.name} ?`,`${circuit.stats.lengthKm} km`,quizNameOptions(`${circuit.stats.lengthKm} km`,CIRCUITS_2026.map(item=>`${item.stats.lengthKm} km`)),'Circuits',`${circuit.name} mesure ${circuit.stats.lengthKm} km.`,{fullHistory:true});
 });
 TEAMS_2026.forEach(team=>{
  add('expert',`Combien de titres constructeurs ${team.name} a-t-elle remportés ?`,team.constructorsTitles,quizNumericOptions(team.constructorsTitles),'Écuries',`${team.name} : ${team.constructorsTitles} titre(s). ${team.scope}`,{fullHistory:true});
  add('expert',`Combien de victoires en Grand Prix sont attribuées à l’identité ${team.name} ?`,team.careerWins,quizNumericOptions(team.careerWins),'Écuries',`${team.name} : ${team.careerWins} victoire(s). ${team.scope}`,{fullHistory:true});
  add('expert',`En quelle année l’identité ${team.name} a-t-elle participé pour la première fois ?`,team.firstEntry,quizNumericOptions(team.firstEntry,'year'),'Écuries',`Première participation sous cette identité : ${team.firstEntry}.`,{fullHistory:true});
 });
 LEGENDS_F1.forEach(legend=>{
  const history=CAREER_DATA.drivers[legend.jolpicaId];
  add('expert',`Combien de titres de champion du monde ${legend.name} a-t-il remportés ?`,legend.titles,quizNumericOptions(legend.titles),'Légendes',legend.titles?`${legend.name} : ${legend.titles} titre(s), en ${legend.titleYears.join(', ')}.`:`${legend.name} n’a jamais remporté le championnat du monde de F1.`,{fullHistory:true});
  add('expert',`Quel pays ${legend.name} représentait-il en Formule 1 ?`,legend.country,quizNameOptions(legend.country,countries),'Légendes',`${legend.name} représentait : ${legend.country}.`,{fullHistory:true});
  if(history.wins.length){const first=CAREER_DATA.events[history.wins.at(-1)];add('expert',`À quel Grand Prix ${legend.name} a-t-il remporté sa première victoire ?`,first.raceName,quizNameOptions(first.raceName,eventNames),'Légendes',`${first.raceName} ${first.season}, à ${first.locality}.`,{fullHistory:true});}
 });

 /* PRO — toutes les catégories, anciennes écuries comprises. */
 DRIVERS_2026.forEach(driver=>{
  const name=`${driver.first} ${driver.last}`,history=CAREER_DATA.drivers[driver.jolpicaId];
  add('pro',`Combien de podiums en Grand Prix ${name} a-t-il obtenus ?`,driver.podiums,quizNumericOptions(driver.podiums),'Pilotes',`${name} : ${driver.podiums} podium(s) en Grand Prix.`,{fullHistory:true,includesHistoricTeams:true});
  if(history.poles.length){const first=CAREER_DATA.events[history.poles.at(-1)];add('pro',`En quelle année ${name} a-t-il obtenu sa première pole position en Grand Prix ?`,first.season,quizNumericOptions(first.season,'year'),'Pilotes',`${first.raceName} ${first.season}, sur ${first.circuit}.`,{fullHistory:true,includesHistoricTeams:true});}
 });
 CIRCUITS_2026.forEach(circuit=>{
  add('pro',`Combien de tours sont prévus sur ${circuit.name} ?`,circuit.stats.laps,quizNumericOptions(circuit.stats.laps),'Circuits',`${circuit.stats.laps} tours sont prévus sur ${circuit.name}.`,{fullHistory:true,includesHistoricTeams:true});
  add('pro',`Quelle distance totale de Grand Prix est prévue à ${circuit.city} ?`,`${circuit.stats.raceDistanceKm} km`,quizNameOptions(`${circuit.stats.raceDistanceKm} km`,CIRCUITS_2026.map(item=>`${item.stats.raceDistanceKm} km`)),'Circuits',`Distance annoncée : ${circuit.stats.raceDistanceKm} km.`,{fullHistory:true,includesHistoricTeams:true});
 });
 TEAMS_2026.forEach(team=>{
  add('pro',`Combien de pole positions sont attribuées à l’identité ${team.name} ?`,team.careerPoles,quizNumericOptions(team.careerPoles),'Écuries',`${team.name} : ${team.careerPoles} pole position(s). ${team.scope}`,{fullHistory:true,includesHistoricTeams:true});
  add('pro',`Quel est le nom complet de l’écurie ${team.name} en 2026 ?`,team.fullName,quizNameOptions(team.fullName,TEAMS_2026.map(item=>item.fullName)),'Écuries',team.fullName,{fullHistory:true,includesHistoricTeams:true});
 });
 LEGENDS_F1.forEach(legend=>{
  const history=CAREER_DATA.drivers[legend.jolpicaId];
  add('pro',`Combien de pole positions ${legend.name} a-t-il obtenues en Grand Prix ?`,legend.poles,quizNumericOptions(legend.poles),'Légendes',`${legend.name} : ${legend.poles} pole position(s) en championnat du monde.`,{fullHistory:true,includesHistoricTeams:true});
  if(history.wins.length){const last=CAREER_DATA.events[history.wins[0]];add('pro',`À quel Grand Prix ${legend.name} a-t-il remporté sa dernière victoire en F1 ?`,last.raceName,quizNameOptions(last.raceName,eventNames),'Légendes',`${last.raceName} ${last.season}, à ${last.locality}, sur ${last.circuit}.`,{fullHistory:true,includesHistoricTeams:true});}
  if(history.titles.length)add('pro',`En quelle année ${legend.name} a-t-il remporté son premier titre mondial ?`,history.titles[0],quizNumericOptions(history.titles[0],'year'),'Légendes',`${legend.name} a été sacré pour la première fois en ${history.titles[0]}.`,{fullHistory:true,includesHistoricTeams:true});
 });
 historicTeams.forEach(team=>{
  add('pro',`En quelle année ${team.name} a-t-elle fait sa première apparition en championnat du monde ?`,team.firstYear,quizNameOptions(team.firstYear,historicFirstYears),'Écuries anciennes',`${team.name} apparaît pour la première fois en ${team.firstYear}.`,{fullHistory:true,includesHistoricTeams:true});
  add('pro',`À quel pays le constructeur historique ${team.name} est-il rattaché ?`,team.country,quizNameOptions(team.country,historicCountries),'Écuries anciennes',`${team.name} est rattaché à : ${team.country}.`,{fullHistory:true,includesHistoricTeams:true});
  add('pro',`Combien de victoires en Grand Prix sont attribuées à ${team.name} ?`,team.wins,quizNumericOptions(team.wins),'Écuries anciennes',`${team.name} : ${team.wins} victoire(s) en Grand Prix sous cette identité.`,{fullHistory:true,includesHistoricTeams:true});
  add('pro',`Combien de titres constructeurs sont attribués à ${team.name} ?`,team.titles,quizNumericOptions(team.titles),'Écuries anciennes',`${team.name} : ${team.titles} titre(s) constructeur sous cette identité.`,{fullHistory:true,includesHistoricTeams:true});
 });

 /* Cent questions par niveau, réparties entre ses catégories. */
 return Object.keys(QUIZ_LEVELS).flatMap(level=>{
  const groups=QUIZ_LEVELS[level].categories.map(category=>all.filter(question=>question.level===level&&question.category===category)),selected=[];
  while(selected.length<100&&groups.some(group=>group.length))for(const group of groups){if(group.length&&selected.length<100)selected.push(group.shift());}
  return selected;
 });
}
const QUIZ_POOL=buildQuizPool();

;
