/* app.js */

const navButtons=[...document.querySelectorAll('.nav-btn')];
const views=[...document.querySelectorAll('.view')];
const pageTitle=document.getElementById('pageTitle');
const sidebar=document.getElementById('sidebar');
const titles={archives:'Saisons & résultats',home:'Le monde de la Formule 1',circuits:'Circuits',drivers:'Pilotes',teams:'Écuries','historic-teams':'Écuries de légende',managers:'Managers',legends:'Légendes F1',quiz:'Challenge GP F1'};

function showView(name){
  views.forEach(v=>v.classList.toggle('active',v.id===`view-${name}`));
  navButtons.forEach(b=>b.classList.toggle('active',b.dataset.view===name));
  pageTitle.textContent=titles[name]||'F1 CONSTANT';
  sidebar.classList.remove('open');

  if(name==='drivers' && typeof showDriverList==='function') showDriverList(false);
  if(name==='teams' && typeof showTeamList==='function') showTeamList(false);
  if(name==='historic-teams' && typeof showHistoricTeamList==='function') showHistoricTeamList(false);
  if(name==='managers' && typeof showManagerList==='function') showManagerList(false);
  if(name==='legends' && typeof showLegendList==='function') showLegendList(false);
  if(name==='quiz' && typeof resetQuizToIntro==='function') resetQuizToIntro(false);

  window.scrollTo({top:0,behavior:'smooth'});
}
navButtons.forEach(b=>b.addEventListener('click',()=>showView(b.dataset.view)));
document.querySelectorAll('[data-jump]').forEach(el=>el.addEventListener('click',()=>showView(el.dataset.jump)));
document.getElementById('menuToggle').addEventListener('click',()=>sidebar.classList.toggle('open'));

const roster=document.getElementById('circuitRoster');
const circuitSearch=document.getElementById('circuitSearch');
const fallbackImg=document.getElementById('circuitSvgImage');
const telemetrySvg=document.getElementById('telemetryMap');
const loading=document.getElementById('trackLoading');
const layerButtons=[...document.querySelectorAll('.layer-btn[data-layer]')];
const toggleAllButton=document.getElementById('toggleAllLayers');
const NS='http://www.w3.org/2000/svg';
const DRIVER_CANDIDATES=['VER','NOR','RUS','LEC','HAM','PIA','ALO','SAI','ALB','PER','BOT','HUL'];
const LAP_CANDIDATES=[10,12,8,15,5,20,25,6,18,30];
const SVG_OVERLAY_CIRCUITS = new Set(['shanghai','monaco','hungaroring']);

let selectedCircuitIndex=Math.max(0,CIRCUITS_2026.findIndex(c=>c.id==='montreal'));
let activeRenderToken=0;
let layerState={sectors:true,turns:true,overtake:true,speed:true,pits:true};
let layerAvailability={sectors:false,turns:false,overtake:false,speed:false,pits:false};
let layoutState=null;

function svgEl(tag,attrs={}){
  const el=document.createElementNS(NS,tag);
  Object.entries(attrs).forEach(([k,v])=>el.setAttribute(k,v));
  return el;
}
function n(v){const x=Number(v);return Number.isFinite(x)?x:null}
function fetchJson(url){return fetch(url,{cache:'no-store'}).then(r=>{if(!r.ok)throw new Error(`${r.status} ${url}`);return r.json()})}

function columnarToRows(json){
  if(!json||typeof json!=='object'||Array.isArray(json))return[];
  const arrays=Object.entries(json).filter(([,v])=>Array.isArray(v));
  if(!arrays.length)return[];
  const count=Math.max(...arrays.map(([,v])=>v.length));
  const rows=Array.from({length:count},()=>({}));
  Object.entries(json).forEach(([k,v])=>{
    if(Array.isArray(v)){for(let i=0;i<count;i++)rows[i][k]=v[i]}
    else{for(let i=0;i<count;i++)rows[i][k]=v}
  });
  return rows;
}
function cornersArray(json){
  if(Array.isArray(json))return json;
  if(Array.isArray(json?.corners))return json.corners;
  return columnarToRows(json);
}
function lapsArray(json){
  if(Array.isArray(json))return json;
  if(Array.isArray(json?.laps))return json.laps;
  if(Array.isArray(json?.lapTimes))return json.lapTimes;
  return columnarToRows(json);
}
function telObj(json){
  const t=json?.tel||json;
  if(!t||!Array.isArray(t.x)||!Array.isArray(t.y)||!Array.isArray(t.distance))throw new Error('Format télémétrie invalide');
  return t;
}
function lapNo(r){return Number(r?.lap??r?.LapNumber??r?.lap_number)}

function setStatus(kind,title,text){
  const box=document.getElementById('dataStatus');
  box.className=`data-status ${kind}`;
  document.getElementById('dataStatusTitle').textContent=title;
  document.getElementById('dataStatusText').textContent=text;
}
function setSource(id,text,ok=false){
  const el=document.getElementById(id); if(!el)return;
  el.textContent=text;el.classList.toggle('ok',ok);
}
function setLayerAvailability(name,available,tooltip=''){
  layerAvailability[name]=!!available;
  const btn=document.querySelector(`.layer-btn[data-layer="${name}"]`);if(!btn)return;
  btn.disabled=!available;
  btn.classList.toggle('unavailable',!available);
  btn.classList.toggle('active',available&&layerState[name]);
  btn.setAttribute('aria-pressed',String(!!available&&!!layerState[name]));
  btn.title=tooltip||(available?'Cliquer pour afficher / masquer':'Donnée non disponible');
}
function applyLayers(){
  Object.keys(layerState).forEach(name=>{
    telemetrySvg.querySelectorAll(`.map-layer-${name}`).forEach(el=>{
      const hidden=!layerState[name]||!layerAvailability[name];
      el.classList.toggle('is-hidden',hidden);el.setAttribute('display',hidden?'none':'inline');
    });
    const btn=document.querySelector(`.layer-btn[data-layer="${name}"]`);
    if(btn){btn.classList.toggle('active',layerAvailability[name]&&layerState[name]);btn.setAttribute('aria-pressed',String(!!layerAvailability[name]&&!!layerState[name]));}
  });
  const avail=Object.keys(layerAvailability).filter(k=>layerAvailability[k]);
  toggleAllButton.textContent=avail.some(k=>layerState[k])?'Tout masquer':'Tout afficher';
}
layerButtons.forEach(btn=>btn.addEventListener('click',()=>{
  const k=btn.dataset.layer;if(!layerAvailability[k])return;
  layerState[k]=!layerState[k];btn.setAttribute('aria-pressed',String(layerState[k]));applyLayers();
}));
toggleAllButton.addEventListener('click',()=>{
  const avail=Object.keys(layerAvailability).filter(k=>layerAvailability[k]);
  const any=avail.some(k=>layerState[k]);avail.forEach(k=>layerState[k]=!any);applyLayers();
});
function resetLayers(){
  Object.keys(layerAvailability).forEach(k=>setLayerAvailability(k,false));
  setSource('sourceSectors','—');setSource('sourceTurns','—');setSource('sourceOvertake','—');
  setSource('sourceSpeed','—');setSource('sourcePits','—');setSource('sourceStart','—');
}

function renderRoster(filter=''){
  const term=filter.trim().toLowerCase();roster.innerHTML='';
  CIRCUITS_2026.forEach((c,i)=>{
    if(term&&!`${c.country} ${c.city} ${c.name}`.toLowerCase().includes(term))return;
    const b=document.createElement('button');b.className='circuit-chip'+(i===selectedCircuitIndex?' active':'');
    b.innerHTML=`<span class="chip-round">${String(c.round).padStart(2,'0')}</span><span>${waveFlag(c.flag,c.country,'waving-flag-small')} ${escapeHtml(c.city)}</span>`;
    b.addEventListener('click',()=>selectCircuit(i));roster.appendChild(b);
  });
  document.getElementById('circuitCount').textContent=roster.querySelectorAll('.circuit-chip').length;
}
function updateOvertakePanel(c){
  const source=MAP_SOURCES[c.id];
  document.getElementById('otDetectionPosition').textContent=source.detection||'Position 2026 : non renseignée';
  document.getElementById('otActivationPosition').textContent=source.activation||'Position 2026 : non renseignée';
  const status=document.getElementById('otSourceStatus');status.className='ot-source-status '+(source.officialOvertake?'verified':'pending');
  status.textContent=source.officialOvertake?'Repères du plan FIA 2026. Placement sur le dessin schématique ; les positions textuelles font référence.':'Zones Overtake 2026 non renseignées : aucun emplacement ajouté par supposition.';
  const link=document.createElement('a');link.href=source.url;link.target='_blank';link.rel='noopener';link.textContent=' Consulter la source';status.appendChild(link);
  return;
  const info=c.overtakeInfo||{};
  const d=document.getElementById('otDetectionPosition'),a=document.getElementById('otActivationPosition'),s=document.getElementById('otSourceStatus');
  d.textContent=Number.isFinite(Number(info.detectionDistance))?`Position : ${Number(info.detectionDistance).toLocaleString('fr-FR')} m depuis la ligne`:
    c.overtake?.detection?'Position : repère officiel relatif au virage':'Position 2026 : en attente de publication FIA';
  a.textContent=Number.isFinite(Number(info.activationDistance))?`Position : ${Number(info.activationDistance).toLocaleString('fr-FR')} m depuis la ligne`:
    c.overtake?.activation?'Position : repère officiel relatif au virage':'Position 2026 : en attente de publication FIA';
  s.className='ot-source-status '+(c.id==='madrid'?'verified':'pending');
  s.textContent=c.id==='madrid'?'FIA · plan du 10/09/2026 · détection à l’entrée de T22 ; activation 20 m après T22.':(Number.isFinite(info.detectionDistance)?'Repères indicatifs repris de l’atlas. À confirmer avec les notes FIA de l’épreuve.':'Zones Overtake 2026 non renseignées : aucun emplacement ajouté par supposition.');
}
function updateCircuitText(c){
  document.getElementById('circuitPageTitle').textContent=c.name;
  document.getElementById('circuitCountryBadge').innerHTML=`${waveFlag(c.flag,c.country,'waving-flag-small')}<span>${escapeHtml(c.country)} · ${escapeHtml(c.city)}</span>`;
  document.getElementById('circuitRoundLabel').textContent=`MANCHE ${String(c.round).padStart(2,'0')} · ${c.country.toUpperCase()}`;
  document.getElementById('circuitName').textContent=c.name;document.getElementById('circuitCity').textContent=c.city;
  document.getElementById('roundNumber').textContent=String(c.round).padStart(2,'0');
  document.getElementById('infoCircuitName').textContent=c.name;document.getElementById('infoCountry').textContent=c.country.split(' /')[0];
  document.getElementById('infoCity').textContent=c.city;document.getElementById('infoRound').textContent=`${c.round} / ${CIRCUITS_2026.length}`;
  document.getElementById('trackFlag').innerHTML=waveFlag(c.flag,c.country,'waving-flag-large');document.getElementById('trackIdentityCity').textContent=c.city;
  document.getElementById('trackIdentityCountry').textContent=c.country;fallbackImg.alt=`Tracé du ${c.name}`;
  updateStatsPanel(c);
  updateOvertakePanel(c);
}

function updateStatsPanel(c){
  const s=c.stats||{};
  document.getElementById('statLength').textContent=s.lengthKm?`${s.lengthKm} km`:'—';
  document.getElementById('statFirstGp').textContent=s.firstGp||'—';
  document.getElementById('statLaps').textContent=s.laps||'—';
  document.getElementById('statFastestLap').textContent=s.fastestLap||'—';
  document.getElementById('statFastestLapDetail').textContent=(s.fastestLapHolder&&s.fastestLapYear)?`${s.fastestLapHolder} (${s.fastestLapYear})`:'Pas encore de record officiel';
  document.getElementById('statRaceDistance').textContent=s.raceDistanceKm?`${s.raceDistanceKm} km`:'—';
  const link=document.getElementById('officialCircuitLink');
  if(link){
    link.href=s.officialUrl||'#';
    link.style.display=s.officialUrl?'inline-flex':'none';
  }
}

async function selectCircuit(index){
 selectedCircuitIndex=(index+CIRCUITS_2026.length)%CIRCUITS_2026.length;
 const c=CIRCUITS_2026[selectedCircuitIndex],m=CIRCUIT_MAPS[c.id],token=++activeRenderToken;
 updateCircuitText(c);renderRoster(circuitSearch.value);resetLayers();loading.style.display='grid';
 document.getElementById('otPopover').hidden=true;
 const url='images/circuits/'+c.id+'.svg';fallbackImg.removeAttribute('src');fallbackImg.style.display='none';telemetrySvg.innerHTML='';telemetrySvg.style.display='none';
 try{
  const raw=CIRCUIT_SVGS[c.id];if(!raw)throw new Error('Carte absente');if(token!==activeRenderToken)return;
  const doc=new DOMParser().parseFromString(raw,'image/svg+xml'),svg=doc.documentElement;
  telemetrySvg.setAttribute('viewBox','0 -35 1000 795');telemetrySvg.setAttribute('font-family','Arial, sans-serif');telemetrySvg.setAttribute('aria-label',c.name+' : virages, départ et voie des stands');
  for(const child of [...svg.childNodes])telemetrySvg.appendChild(document.importNode(child,true));
  telemetrySvg.style.display='block';
  Object.entries(m.available).forEach(([k,v])=>setLayerAvailability(k,v));applyLayers();
 }catch(e){if(token!==activeRenderToken)return;fallbackImg.style.display='block';fallbackImg.classList.add('loaded');}
 if(token!==activeRenderToken)return;
 loading.style.display='none';
 const ref=m.manual?'Plan du circuit':m.sourceYear?'Repères '+m.sourceYear:'Plan du circuit';
 setSource('sourceSectors',MAP_SOURCES[c.id].sectorLabel,m.available.sectors);
 setSource('sourceTurns',m.corners?m.corners+' virages · '+ref:'Non renseignés',!!m.corners);
 setSource('sourcePits',m.available.pits?'Voie noire · '+ref:'Non renseignés',m.available.pits);
 setSource('sourceStart',m.hasStart?'Damier · '+ref:'Non renseignée',m.hasStart);
 setSource('sourceSpeed',m.available.speed?'Point de mesure':'Non renseigné',m.available.speed);
 setSource('sourceOvertake',m.available.overtake?'FIA 2026 · repères schématiques':'Non renseignés',m.available.overtake);
 document.getElementById('infoFormat').textContent='Carte vectorielle';
 setStatus('verified','Les repères du circuit','Damier : départ · voie noire : stands · numéros bleus : virages.');
 document.getElementById('diagramNote').textContent='Tracé et largeur de voie schématiques. Secteurs : '+MAP_SOURCES[c.id].sectorLabel+'. Les boutons fonctionnent aussi hors ligne. L’export conserve les calques choisis et présente le circuit entier, indépendamment du zoom.';
}
let mapZoom=1;
document.getElementById('mapZoomIn')?.addEventListener('click',()=>setMapZoom(Math.min(3,mapZoom+.25)));
document.getElementById('mapZoomOut')?.addEventListener('click',()=>setMapZoom(Math.max(1,mapZoom-.25)));
function setMapZoom(value){mapZoom=value;telemetrySvg.style.width=(value*100)+'%';telemetrySvg.style.maxWidth='none';fallbackImg.style.width=(value*100)+'%';document.getElementById('mapZoomValue').textContent=Math.round(value*100)+' %';}
document.getElementById('prevCircuit').addEventListener('click',()=>selectCircuit(selectedCircuitIndex-1));
document.getElementById('nextCircuit').addEventListener('click',()=>selectCircuit(selectedCircuitIndex+1));
circuitSearch.addEventListener('input',e=>renderRoster(e.target.value));


