const legendsGrid=document.getElementById('legendsGrid');
const legendSearch=document.getElementById('legendSearch');
const legendsListPanel=document.getElementById('legendsListPanel');
const legendDetailPanel=document.getElementById('legendDetailPanel');

function legendById(id){
  return (typeof LEGENDS_F1!=='undefined') ? LEGENDS_F1.find(l=>l.id===id) : null;
}
function showLegendList(scroll=true){
  if(!legendsListPanel||!legendDetailPanel) return;
  legendsListPanel.hidden=false;
  legendDetailPanel.hidden=true;
  if(scroll) window.scrollTo({top:0,behavior:'smooth'});
}
function legendCard(l){
  const card=document.createElement('article');
  card.className='legend-card';
  const titleText=l.titles>0?`${l.titles}× CHAMPION`:'ICÔNE F1';
  card.innerHTML=`
    ${l.image?`<img class="legend-portrait" src="${escapeHtml(l.image)}" alt="${escapeHtml(l.name)}" loading="lazy">`:""}
    <div class="legend-card-era">${l.years}</div>
    <div class="legend-card-country">${waveFlag(l.flag,l.country,'waving-flag-small')}<span>${escapeHtml(l.country)}</span></div>
    <h3>${l.name}</h3>
    <div class="legend-card-stats">
      <span><b>${l.titles}</b> titre${l.titles>1?'s':''}</span>
      <span><b>${l.wins}</b> victoire${l.wins>1?'s':''}</span>
      <span><b>${l.poles}</b> pole${l.poles>1?'s':''}</span>
    </div>
    <p>${l.fact}</p>
    <div class="legend-card-badge">${titleText}</div>
  `;
  const open=()=>openLegendDetail(l.id);
  card.addEventListener('click',open);
  card.setAttribute('role','button');
  card.setAttribute('tabindex','0');
  card.setAttribute('aria-label',`Ouvrir la fiche de ${l.name}`);
  card.addEventListener('keydown',e=>{
    if(e.key==='Enter'||e.key===' '){e.preventDefault();open();}
  });
  return card;
}
function renderLegends(filter=''){
  if(!legendsGrid||typeof LEGENDS_F1==='undefined') return;
  const term=filter.trim().toLowerCase();
  legendsGrid.innerHTML='';
  const filtered=LEGENDS_F1.filter(l=>`${l.name} ${l.country} ${l.years} ${l.fact} ${(l.careerTeams||[]).join(' ')}`.toLowerCase().includes(term));
  filtered.forEach(l=>legendsGrid.appendChild(legendCard(l)));
  const count=document.getElementById('legendCount');
  if(count) count.textContent=filtered.length;
}
function openLegendDetail(id){
  const l=legendById(id); if(!l) return;
  legendsListPanel.hidden=true;
  legendDetailPanel.hidden=false;
  document.getElementById('legendDetailName').textContent=l.name;
  document.getElementById('legendDetailEra').textContent=l.years;
  document.getElementById('legendDetailCountry').innerHTML=`${waveFlag(l.flag,l.country,'waving-flag-medium')}<span>${escapeHtml(l.country)}</span>`;
  document.getElementById('legendDetailTitlesBg').textContent=l.titles>0?`${l.titles}×`:'F1';
  document.getElementById('legendStatTitles').textContent=l.titles;
  document.getElementById('legendStatWins').textContent=l.wins;
  document.getElementById('legendStatPoles').textContent=l.poles;
  document.getElementById('legendFact').textContent=l.fact;
  document.getElementById('legendBio').textContent=l.bio;
  renderCareerTeams('legendCareerTeams',l.careerTeamPeriods);
  const photo=document.getElementById('legendDetailImage');photo.hidden=!l.image;if(l.image){photo.src=l.image;photo.alt=l.name;}
  document.getElementById('legendPhotoCredit').innerHTML=l.photoPage?`<a href="${escapeHtml(l.photoPage)}" target="_blank" rel="noopener">Photo : ${escapeHtml(l.photoCredit)} · ${escapeHtml(l.photoLicense)} ↗</a>`:'';
  loadDriverHistoryInto(l.jolpicaId,'legendWinsHistory','legendPolesHistory');
  window.scrollTo({top:0,behavior:'smooth'});
}
legendSearch?.addEventListener('input',e=>renderLegends(e.target.value));
document.getElementById('legendDetailBack')?.addEventListener('click',()=>showLegendList());
renderLegends();

/* =========================
   CHALLENGE GP F1 — 10 / 300
   ========================= */
const quizIntro=document.getElementById('quizIntro');
const quizGame=document.getElementById('quizGame');
const quizResult=document.getElementById('quizResult');
const quizStartBtn=document.getElementById('quizStartBtn');
const quizReplayBtn=document.getElementById('quizReplayBtn');
const quizNextBtn=document.getElementById('quizNextBtn');
const quizOptions=document.getElementById('quizOptions');
const quizFeedback=document.getElementById('quizFeedback');

let quizLevel='amateur';
let answerSlots=[];
let quizQuestions=[];
let quizIndex=0;
let quizScoreValue=0;
let quizAnswered=false;

function shuffleArray(arr){
  const a=[...arr];
  for(let i=a.length-1;i>0;i--){
    const j=Math.floor(Math.random()*(i+1));
    [a[i],a[j]]=[a[j],a[i]];
  }
  return a;
}
function resetQuizToIntro(scroll=true){
  if(!quizIntro||!quizGame||!quizResult) return;
  quizIntro.hidden=false;
  quizGame.hidden=true;
  quizResult.hidden=true;
  quizResult.classList.remove('outcome-pole','outcome-silver','outcome-bronze','outcome-pit','outcome-zero');
  clearConfetti();
  if(scroll) window.scrollTo({top:0,behavior:'smooth'});
}
function startQuiz(){
  const pool=QUIZ_POOL.filter(q=>q.level===quizLevel),key='f1constant-quiz-v17-'+quizLevel;
  let remaining=[];try{remaining=JSON.parse(localStorage.getItem(key)||'[]').filter(id=>pool.some(q=>q.id===id));}catch{}
  const chosen=[];
  while(chosen.length<10){if(!remaining.length)remaining=shuffleArray(pool.filter(q=>!chosen.includes(q.id)).map(q=>q.id));chosen.push(remaining.pop());}
  try{localStorage.setItem(key,JSON.stringify(remaining));}catch{}
  quizQuestions=chosen.map(id=>pool.find(q=>q.id===id));
  const choices=QUIZ_LEVELS[quizLevel].choices;
  answerSlots=shuffleArray(Array.from({length:10},(_,i)=>i%choices));
  clearConfetti();
  quizIndex=0;
  quizScoreValue=0;
  quizAnswered=false;
  quizIntro.hidden=true;
  quizResult.hidden=true;
  quizGame.hidden=false;
  renderQuizQuestion();
  window.scrollTo({top:0,behavior:'smooth'});
}
let quizRenderedOptions=[];

function renderQuizQuestion(){
  const q=quizQuestions[quizIndex];
  quizAnswered=false;
  document.getElementById('quizProgress').textContent=`${quizIndex+1} / 10`;
  document.getElementById('quizScore').textContent=quizScoreValue;
  document.getElementById('quizProgressFill').style.width=`${((quizIndex+1)/10)*100}%`;
  document.getElementById('quizCategory').textContent=QUIZ_LEVELS[quizLevel].label+' · '+q.category;
  document.getElementById('quizQuestion').textContent=q.q;
  quizFeedback.hidden=true;
  quizFeedback.className='quiz-feedback';
  quizNextBtn.hidden=true;
  quizOptions.innerHTML='';

  const wrong=shuffleArray(q.options.filter((_,i)=>i!==q.answer)).slice(0,QUIZ_LEVELS[quizLevel].choices-1);
  quizRenderedOptions=wrong.map(text=>({text,correct:false}));
  quizRenderedOptions.splice(answerSlots[quizIndex],0,{text:q.options[q.answer],correct:true});

  quizRenderedOptions.forEach((opt,idx)=>{
    const b=document.createElement('button');
    b.className='quiz-option';
    b.dataset.correct=opt.correct?'1':'0';
    b.innerHTML=`<span>${String.fromCharCode(65+idx)}</span><strong>${opt.text}</strong>`;
    b.addEventListener('click',()=>answerQuiz(opt.correct,b));
    quizOptions.appendChild(b);
  });
}
function answerQuiz(isCorrect,button){
  if(quizAnswered) return;
  quizAnswered=true;
  const q=quizQuestions[quizIndex];
  const buttons=[...quizOptions.querySelectorAll('.quiz-option')];
  buttons.forEach(b=>{
    b.disabled=true;
    if(b.dataset.correct==='1') b.classList.add('correct');
  });

  if(isCorrect){
    quizScoreValue++;
    button.classList.add('chosen-correct');
    quizFeedback.textContent=`✓ Bonne réponse — ${q.explanation}`;
    quizFeedback.classList.add('good');
  }else{
    button.classList.add('wrong');
    quizFeedback.textContent=`✕ Pas cette fois — ${q.explanation}`;
    quizFeedback.classList.add('bad');
  }
  document.getElementById('quizScore').textContent=quizScoreValue;
  quizFeedback.hidden=false;
  quizNextBtn.textContent=quizIndex===9?'Voir le résultat →':'Question suivante →';
  quizNextBtn.hidden=false;
}
function nextQuiz(){
  if(!quizAnswered) return;
  if(quizIndex>=9){finishQuiz();return;}
  quizIndex++;
  renderQuizQuestion();
}
function clearConfetti(){
  const layer=document.getElementById('confettiLayer');
  if(layer) layer.innerHTML='';
}
function launchConfetti(multiplier=1,palette='rainbow'){
  const layer=document.getElementById('confettiLayer');
  if(!layer) return;
  layer.innerHTML='';
  const count=50*multiplier,colors=palette==='gold'?['#ffd54a','#fff4b0','#ff8a32','#ffffff']:palette==='silver'?['#e8edf2','#8fa1b2','#ffffff','#7bdcff']:palette==='bronze'?['#dc9558','#8d542d','#ffd2a8','#ffffff']:[];
  for(let i=0;i<count;i++){
    const s=document.createElement('i');
    s.style.setProperty('--x',`${Math.random()*100}%`);
    s.style.setProperty('--delay',`${Math.random()*.8}s`);
    s.style.setProperty('--dur',`${1.8+Math.random()*1.6}s`);
    s.style.setProperty('--rot',`${Math.floor(Math.random()*720)-360}deg`);
    if(colors.length)s.style.background=colors[i%colors.length];else s.style.setProperty('--h',`${Math.floor(Math.random()*360)}deg`);
    layer.appendChild(s);
  }
}
function finishQuiz(){
  quizGame.hidden=true;
  quizResult.hidden=false;
  document.getElementById('quizFinalScore').textContent=quizScoreValue;

  const podium=document.getElementById('podiumStage');
  const loser=document.getElementById('loserVisual');
  podium.classList.remove('tier-1','tier-2','tier-3');
  quizResult.classList.remove('outcome-pole','outcome-silver','outcome-bronze','outcome-pit','outcome-zero');
  loser.classList.remove('zero-score');
  podium.hidden=false;
  loser.hidden=true;
  clearConfetti();

  const title=document.getElementById('quizResultTitle');
  const text=document.getElementById('quizResultText');

  if(quizScoreValue>=8){
    podium.hidden=false;
    loser.hidden=true;
    podium.classList.add('tier-1');
    quizResult.classList.add('outcome-pole');
    title.textContent='P1 — LA PÔLE POSITION !!!';
    text.textContent='Objectif du challenge atteint : la pole position ! Bravo Constant.';
    launchConfetti(3,'gold');
  }else if(quizScoreValue>=6){
    podium.hidden=false;
    loser.hidden=true;
    podium.classList.add('tier-2');
    quizResult.classList.add('outcome-silver');
    title.textContent='P2 — Très solide !';
    text.textContent='Deuxième marche du podium. Encore un petit effort pour la victoire.';
    launchConfetti(2,'silver');
  }else if(quizScoreValue>=4){
    podium.hidden=false;
    loser.hidden=true;
    podium.classList.add('tier-3');
    quizResult.classList.add('outcome-bronze');
    title.textContent='P3 — Podium !';
    text.textContent='Troisième marche. Le champagne est là, mais la pole reste à chercher.';
    launchConfetti(2,'bronze');
  }else{
    podium.hidden=true;
    loser.hidden=false;
    if(quizScoreValue===0){
      loser.classList.add('zero-score');quizResult.classList.add('outcome-zero');
      title.textContent='ZÉRO ! La monoplace a tout perdu !';
      text.textContent='Moteur fumant, pièces éparpillées et roues envolées : dépannage immédiat et retour direct aux stands !';
    }else{
      quizResult.classList.add('outcome-pit');
      title.textContent='Retour aux stands !';
      text.textContent='Entre 1 et 3 bonnes réponses : arrêt au stand un peu mouvementé, mais l’équipe est prête pour repartir !';
    }
  }
  window.scrollTo({top:0,behavior:'smooth'});
}
document.querySelectorAll('[data-quiz-level]').forEach(b=>b.addEventListener('click',()=>{quizLevel=b.dataset.quizLevel;document.querySelectorAll('[data-quiz-level]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b));});}));
document.getElementById('quizChangeLevel')?.addEventListener('click',()=>resetQuizToIntro());
quizStartBtn?.addEventListener('click',startQuiz);
quizReplayBtn?.addEventListener('click',startQuiz);
quizNextBtn?.addEventListener('click',nextQuiz);
resetQuizToIntro(false);

renderRoster();selectCircuit(selectedCircuitIndex);

;
