/* historic-teams-ui.js */
(function(){
  const media=HISTORIC_MEDIA;
  const credit=a=>`${escapeHtml(a.author)} · <a href="${escapeHtml(a.page)}" target="_blank" rel="noopener">Source</a> · <a href="${escapeHtml(a.licenseUrl||a.page)}" target="_blank" rel="noopener">${escapeHtml(a.license)}</a>`;
  const data=window.HISTORIC_TEAMS||HISTORIC_TEAMS;
  const grid=document.getElementById('historicTeamsGrid');
  const listPanel=document.getElementById('historicTeamsListPanel');
  const detailPanel=document.getElementById('historicTeamDetailPanel');
  const search=document.getElementById('historicTeamSearch');
  const era=document.getElementById('historicTeamEra');
  const sort=document.getElementById('historicTeamSort');
  if(!grid||!data)return;

  const filter=document.createElement('label');filter.className='historic-media-filter';filter.innerHTML='<input type="checkbox" id="historicPhotosOnly"> Voir uniquement les écuries avec une voiture en photo ou en illustration';grid.before(filter);const photosOnly=filter.querySelector('input');photosOnly.addEventListener('change',()=>renderHistoricTeams());
  const flagFromCode=code=>{
    if(!code||code.length!==2)return '🏁';
    return String.fromCodePoint(...code.toUpperCase().split('').map(char=>127397+char.charCodeAt(0)));
  };
  const flagMarkup=(code,country,modifier='')=>waveFlag(flagFromCode(code),country,modifier);
  const period=team=>team.firstYear===team.lastYear?String(team.firstYear):`${team.firstYear}–${team.lastYear}`;

  data.eras.forEach(item=>{
    era.add(new Option(`${item.label} · ${item.evolution}`,item.label));
    const chip=document.createElement('button');
    chip.type='button';chip.dataset.era=item.label;
    chip.innerHTML=`<strong>${item.label}</strong><span>${item.evolution}</span>`;
    chip.addEventListener('click',()=>{era.value=item.label;renderHistoricTeams();});
    document.getElementById('historicEraStrip').appendChild(chip);
  });

  function historicTeamCard(team){
    const card=document.createElement('article');
    card.className='historic-team-card';
    card.style.setProperty('--historic-a',team.teamA);
    card.style.setProperty('--historic-b',team.teamB);
    const m=media[team.id]||{};
    card.innerHTML=`${m.car?`<figure class="historic-car-photo"><img src="${m.car.src}" alt="${escapeHtml(m.car.model)}" loading="lazy"><figcaption>${escapeHtml(m.car.model)}</figcaption></figure>`:''}
      <div class="historic-team-mark" title="${escapeHtml(team.markLabel)}" aria-hidden="true">${m.logo?`<img src="${m.logo.src}" alt="Logo ${escapeHtml(team.name)}">`:escapeHtml(team.mark)}</div>
      <div class="historic-team-card-copy">
        <div class="historic-team-topline"><span>${period(team)}</span><span>${team.seasons} saison${team.seasons>1?'s':''}</span></div>
        <h3>${escapeHtml(team.name)}</h3>
        <p>${escapeHtml(team.fullName)}</p>
        <div class="historic-team-country">${flagMarkup(team.countryCode,team.country,'waving-flag-small')}<span>${escapeHtml(team.country)}</span></div>
        <div class="historic-team-stats"><span><b>${team.wins}</b> victoire${team.wins>1?'s':''}</span><span><b>${team.titles}</b> titre${team.titles>1?'s':''}</span></div>
      </div>`;
    const open=()=>openHistoricTeamDetail(team.id);
    card.tabIndex=0;card.setAttribute('role','button');card.setAttribute('aria-label',`Ouvrir la fiche de ${team.name}`);
    card.addEventListener('click',open);
    card.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();open();}});
    return card;
  }

  window.showHistoricTeamList=function(scrollToTop=true){
    listPanel.hidden=false;detailPanel.hidden=true;
    if(scrollToTop)window.scrollTo({top:0,behavior:'smooth'});
  };

  window.renderHistoricTeams=function(){
    const term=(search.value||'').trim().toLocaleLowerCase('fr');
    let teams=data.teams.filter(team=>{
      const matchesEra=!era.value||team.era===era.value;
      const haystack=`${team.name} ${team.fullName} ${team.country} ${team.firstYear} ${team.lastYear} ${team.years.join(' ')}`.toLocaleLowerCase('fr');
      return matchesEra&&(!photosOnly.checked||!!media[team.id]?.car)&&(!term||haystack.includes(term));
    });
    teams=[...teams].sort((a,b)=>{
      if(sort.value==='wins')return b.wins-a.wins||b.titles-a.titles||a.name.localeCompare(b.name,'fr');
      if(sort.value==='titles')return b.titles-a.titles||b.wins-a.wins||a.name.localeCompare(b.name,'fr');
      if(sort.value==='name')return a.name.localeCompare(b.name,'fr');
      return a.firstYear-b.firstYear||a.name.localeCompare(b.name,'fr');
    });
    grid.innerHTML='';
    teams.forEach(team=>grid.appendChild(historicTeamCard(team)));
    document.getElementById('historicTeamCount').textContent=teams.length;
    document.querySelectorAll('#historicEraStrip button').forEach(button=>button.classList.toggle('active',button.dataset.era===era.value));
    if(!teams.length)grid.innerHTML='<p class="historic-empty">Aucune écurie ne correspond à ces critères.</p>';
  };

  window.openHistoricTeamDetail=function(id){
    const team=data.teams.find(item=>item.id===id);if(!team)return;
    listPanel.hidden=true;detailPanel.hidden=false;
    const hero=document.getElementById('historicTeamDetailHero');
    hero.style.setProperty('--historic-a',team.teamA);hero.style.setProperty('--historic-b',team.teamB);
    const m=media[team.id]||{};
    document.getElementById('historicTeamDetailMark').innerHTML=m.logo?`<img style="width:100%;height:100%;object-fit:contain" src="${m.logo.src}" alt="Logo ${escapeHtml(team.name)}">`:escapeHtml(team.mark);
    document.getElementById('historicTeamGallery').innerHTML=['car','logo'].filter(k=>m[k]).map(k=>{const a=m[k];return `<figure class="historic-${k}-figure"><img src="${a.src}" alt="${escapeHtml(k==='car'?a.model:'Logo '+team.name)}"><figcaption><strong>${escapeHtml(k==='car'?a.model:'Logo '+team.name)}</strong><br>${credit(a)}</figcaption></figure>`;}).join('')||'<p class="historic-no-media">Aucune photographie documentée disponible pour cette écurie dans cette édition.</p>';
    document.getElementById('historicTeamDetailMark').title=team.markLabel;
    document.getElementById('historicTeamDetailName').textContent=team.name;
    document.getElementById('historicTeamDetailFullName').textContent=team.fullName;
    document.getElementById('historicTeamDetailCountry').innerHTML=`${flagMarkup(team.countryCode,team.country,'waving-flag-medium')}<span>${escapeHtml(team.country)}</span>`;
    document.getElementById('historicTeamDetailYears').textContent=period(team);
    document.getElementById('historicTeamDetailEra').textContent=`${team.era} · ${team.evolution}`;
    document.getElementById('historicStatTitles').textContent=team.titles;
    document.getElementById('historicStatWins').textContent=team.wins;
    document.getElementById('historicStatPodiums').textContent=team.podiums;
    document.getElementById('historicStatPoles').textContent=team.poles;
    document.getElementById('historicStatStarts').textContent=team.starts;
    document.getElementById('historicStatSeasons').textContent=team.seasons;
    document.getElementById('historicFirstYear').textContent=team.firstYear;
    document.getElementById('historicLastYear').textContent=team.lastYear;
    document.getElementById('historicBestChampionship').textContent=team.bestChampionship?`P${team.bestChampionship}`:'Non classé';
    document.getElementById('historicBestRace').textContent=team.bestRaceResult?`P${team.bestRaceResult}`:'Non renseigné';
    document.getElementById('historicEvolution').textContent=`${team.era} · ${team.evolution}`;
    document.getElementById('historicSeasonRange').textContent=`${team.seasons} saison${team.seasons>1?'s':''} entre ${team.firstYear} et ${team.lastYear}`;
    document.getElementById('historicYears').innerHTML=team.years.map(year=>`<button type="button" data-season="${year}">${year}</button>`).join('');
    document.querySelectorAll('#historicYears [data-season]').forEach(b=>b.addEventListener('click',()=>openArchiveSeason(Number(b.dataset.season))));
    window.scrollTo({top:0,behavior:'smooth'});
  };

  search.addEventListener('input',renderHistoricTeams);
  era.addEventListener('change',renderHistoricTeams);
  sort.addEventListener('change',renderHistoricTeams);
  document.getElementById('historicTeamDetailBack').addEventListener('click',()=>showHistoricTeamList());
  renderHistoricTeams();
})();

;
/* map-export.js */
/* Self-contained SVG: local files, no external fonts or image dependencies. */
function makeCircuitExport(){
 const c=CIRCUITS_2026[selectedCircuitIndex],s=c.stats||{};
 const root=svgEl('svg',{xmlns:NS,viewBox:'0 0 1320 830','font-family':'Arial, sans-serif'});
 root.appendChild(svgEl('rect',{width:1320,height:830,fill:'white'}));
 const text=(value,x,y,size=17,color='#17283e')=>{const t=svgEl('text',{x,y,'font-size':size,fill:color});t.textContent=value;root.appendChild(t);};
 const measure=document.createElement('canvas').getContext('2d');
 const wrap=(value,maxWidth,size)=>{
  measure.font=size+'px Arial';const lines=[];let line='';
  for(const word of String(value).split(/\s+/)){
   const next=line?line+' '+word:word;
   if(line&&measure.measureText(next).width>maxWidth){lines.push(line);line=word;}else line=next;
  }
  if(line)lines.push(line);return lines;
 };
 const fitText=(value,x,y,size,maxWidth,color='#17283e')=>{
  const t=svgEl('text',{x,y,'font-size':size,fill:color});t.textContent=value;
  measure.font=size+'px Arial';if(measure.measureText(value).width>maxWidth){t.setAttribute('textLength',maxWidth);t.setAttribute('lengthAdjust','spacingAndGlyphs');}
  root.appendChild(t);
 };
 wrap('F1 CONSTANT  /  '+c.name,780,24).forEach((line,i)=>fitText(line,28,49+i*31,24,780));
 // The export uses the exact same curved artwork as the visible identity card.
 const badgeX=849,badgeY=13,badgeW=443,badgeH=113;
 root.appendChild(svgEl('rect',{x:badgeX,y:badgeY,width:badgeW,height:badgeH,rx:25,fill:'#fff',stroke:'#d7dee8'}));
 const code=Array.from(c.flag||'').map(x=>x.codePointAt(0)-127397).filter(x=>x>=65&&x<=90).map(x=>String.fromCharCode(x)).join('').toLowerCase();
 if(code&&WAVING_FLAG_DATA[code])root.appendChild(svgEl('image',{x:badgeX+19,y:badgeY+20,width:87,height:73,href:WAVING_FLAG_DATA[code]}));
 const cityLines=wrap(c.city,300,26),countryLines=wrap(c.country,300,18);
 const copyHeight=cityLines.length*30+countryLines.length*22+5;
 const copyY=badgeY+(badgeH-copyHeight)/2+25;
 cityLines.forEach((line,i)=>fitText(line,badgeX+122,copyY+i*30,26,300,'#141922'));
 countryLines.forEach((line,i)=>fitText(line,badgeX+122,copyY+cityLines.length*30+3+i*22,18,300,'#7a8493'));
 const map=telemetrySvg.cloneNode(true);map.removeAttribute('id');map.removeAttribute('style');map.setAttribute('x','0');map.setAttribute('y','139');map.setAttribute('width','1000');map.setAttribute('height','661');
 map.querySelectorAll('[display="none"],.is-hidden').forEach(el=>el.remove());root.appendChild(map);
 root.appendChild(svgEl('line',{x1:1015,x2:1015,y1:153,y2:785,stroke:'#dce3eb'}));
 const entries=[['LONGUEUR',`${s.lengthKm||'—'} km`],['TOURS',s.laps||'—'],['DISTANCE DU GRAND PRIX',`${s.raceDistanceKm||'—'} km`],['PREMIER GRAND PRIX',s.firstGp||'—'],['RECORD EN COURSE',s.fastestLap||'—']];
 entries.forEach(([label,value],i)=>{text(label,1040,190+i*76,12,'#697a8d');text(value,1040,219+i*76,23);});
 text('CALQUES AFFICHÉS',1040,620,12,'#697a8d');
 const labels={sectors:'Secteurs S1 / S2 / S3',turns:'Numéros des virages',speed:'Speed trap',overtake:'Overtake : détection / activation',pits:'Voie des stands'};
 Object.keys(layerState).filter(k=>layerState[k]&&layerAvailability[k]).forEach((k,i)=>text(labels[k],1040,650+i*23,14));
 text('Carte de repérage schématique · sources et positions textuelles dans MAP_SOURCES.md et la fiche du circuit.',28,819,12,'#697a8d');
 return root;
}
document.getElementById('exportCircuitJpeg').addEventListener('click',async()=>{
 const button=document.getElementById('exportCircuitJpeg'),status=document.getElementById('mapExportStatus');button.disabled=true;status.textContent='Préparation du JPEG…';let url;
 try{
  const xml=new XMLSerializer().serializeToString(makeCircuitExport());url=URL.createObjectURL(new Blob([xml],{type:'image/svg+xml;charset=utf-8'}));
  const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=url;});
  const canvas=document.createElement('canvas');canvas.width=2640;canvas.height=1660;canvas.getContext('2d').drawImage(img,0,0,2640,1660);
  const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.95));if(!blob)throw new Error('Image indisponible');
  const downloadURL=URL.createObjectURL(blob),a=document.createElement('a');a.href=downloadURL;a.download='F1-CONSTANT-'+CIRCUITS_2026[selectedCircuitIndex].id+'.jpg';a.click();setTimeout(()=>URL.revokeObjectURL(downloadURL),30000);
  status.textContent='JPEG téléchargé avec les calques sélectionnés.';
 }catch(e){status.textContent='Export JPEG indisponible dans ce navigateur.';}
 finally{if(url)URL.revokeObjectURL(url);button.disabled=false;}
});

;
