/* standings.js */
/* Public Jolpica API. Atomic driver + constructor updates, with offline fallback. */
(()=>{
 const KEY='f1-constant-standings-v15',TTL=15*60*1000,API='https://api.jolpi.ca/ergast/f1/2026/';
 const status=document.getElementById('standingsStatus'),button=document.getElementById('refreshStandings'),source=document.getElementById('standingsSource');let current=STANDINGS_SNAPSHOT,busy=false;
 function valid(s){return s&&s.season===2026&&Number.isInteger(s.round)&&s.round>0&&s.round<=30&&/^2026-\d{2}-\d{2}$/.test(s.raceDate)&&Date.parse(s.raceDate)<=Date.now()&&['drivers','constructors'].every(k=>Array.isArray(s[k])&&s[k].length>=(k==='drivers'?20:10)&&s[k].length<40&&new Set(s[k].map(r=>r.position)).size===s[k].length&&s[k].every(r=>Number.isInteger(r.position)&&r.position>0&&typeof r.name==='string'&&r.name.length<100&&Number.isFinite(r.points)&&r.points>=0));}
 function draw(message=''){
  const pale=(hex,white=.82)=>{const m=/^#([0-9a-f]{6})$/i.exec(hex||'');if(!m)return '#f5f7f9';const n=parseInt(m[1],16);return `rgb(${[n>>16,(n>>8)&255,n&255].map(v=>Math.round(v+(255-v)*white)).join(',')})`;};
  for(const [key,id] of [['drivers','driverStandingsBody'],['constructors','constructorStandingsBody']]){
   const body=document.getElementById(id);body.replaceChildren();
   [...current[key]].sort((a,b)=>a.position-b.position).forEach(r=>{const row=document.createElement('tr');row.dataset.teamId=r.teamId||'';row.style.setProperty('--team-a',r.teamA||'#aeb7c1');row.style.setProperty('--team-b',r.teamB||'#dce2e8');row.style.setProperty('--team-bg-a',pale(r.teamA,.79));row.style.setProperty('--team-bg-b',pale(r.teamB,.88));[r.position,r.name,r.points.toLocaleString('fr-FR')].forEach(v=>{const cell=document.createElement('td');cell.textContent=v;row.appendChild(cell);});body.appendChild(row);});
  }
  status.textContent='Après la manche '+current.round+' · '+new Date(current.raceDate+'T12:00:00Z').toLocaleDateString('fr-FR')+(message?' — '+message:'');
  source.href=current.source==='https://api.jolpi.ca/ergast/f1/2026/'?current.source:'https://github.com/f1db/f1db';source.textContent='Source : '+(current.sourceName||'Jolpica / Ergast');
 }
 try{const cached=JSON.parse(localStorage.getItem(KEY));if(valid(cached)&&cached.round>=current.round)current=cached;}catch(e){}
 draw('copie disponible hors ligne');
 async function refresh(force=false){
  if(busy)return;if(!navigator.onLine){draw('hors ligne · dernier classement conservé');return;}
  if(!force&&current.savedAt&&Date.now()-current.savedAt<TTL){draw('classement récemment actualisé');return;}
  busy=true;button.disabled=true;button.setAttribute('aria-busy','true');status.textContent='Vérification des classements…';
  const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000);
  const get=async endpoint=>{const r=await fetch(API+endpoint+'?limit=100',{signal:controller.signal,cache:'no-store'});if(!r.ok)throw Error('HTTP');return r.json();};
  try{
   const results=await get('last/results/'),race=results.MRData?.RaceTable?.Races?.[0],round=Number(race?.round);
   if(!race||race.season!=='2026'||!Number.isInteger(round)||round<current.round||Date.parse(race.date)>Date.now())throw Error('Manche incohérente');
   const [drivers,constructors]=await Promise.all([get(round+'/driverstandings/'),get(round+'/constructorstandings/')]);
   const teamStyle=id=>{const aliases={red_bull:'redbull',rb:'racingbulls',aston_martin:'astonmartin',kick_sauber:'audi',sauber:'audi'};const team=TEAMS_2026.find(t=>t.id===(aliases[id]||id));const driver=DRIVERS_2026.find(d=>d.id===team?.drivers?.[0]);return {teamA:driver?.teamA||team?.teamA||'#edf1f5',teamB:driver?.teamB||team?.teamB||'#f9fafb'};};
   const unpack=(d,kind)=>{const list=d.MRData?.StandingsTable?.StandingsLists?.[0];if(list?.season!=='2026'||Number(list.round)!==round)throw Error('Classement incohérent');return list[kind+'Standings'].map(r=>{const constructor=kind==='Driver'?r.Constructors?.at(-1):r.Constructor;return {position:Number(r.position),name:kind==='Driver'?r.Driver.givenName+' '+r.Driver.familyName:r.Constructor.name,points:Number(r.points),teamId:constructor?.constructorId,...teamStyle(constructor?.constructorId)};});};
   const next={season:2026,round,raceDate:race.date,savedAt:Date.now(),source:API,sourceName:'Jolpica / Ergast',drivers:unpack(drivers,'Driver'),constructors:unpack(constructors,'Constructor')};
   if(!valid(next))throw Error('Données invalides');current=next;try{localStorage.setItem(KEY,JSON.stringify(current));}catch(e){}
   draw('actualisé à '+new Date().toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'}));
  }catch(e){console.warn('Classements :',e.message);draw('mise à jour indisponible · dernier classement conservé');}
  finally{clearTimeout(timer);busy=false;button.disabled=false;button.setAttribute('aria-busy','false');}
 }
 button.addEventListener('click',()=>refresh(true));window.addEventListener('online',()=>refresh(true));window.addEventListener('offline',()=>draw('hors ligne · dernier classement conservé'));
 setInterval(()=>{if(!document.hidden)refresh();},TTL);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh();});refresh();
})();

;
