/* archives.js */
/* Season archive: published standings, full classifications and shared podiums. */
(()=>{
 const A=F1_ARCHIVE,yearSelect=document.getElementById('archiveYear');
 const esc=escapeHtml;let selectedYear=2026,tab='standings';
 const flag=code=>code?waveFlag(String.fromCodePoint(...code.toUpperCase().split('').map(c=>127397+c.charCodeAt(0))),'','waving-flag-small'):'';
 const pts=value=>value===null||value===undefined?'—':Number(value).toLocaleString('fr-FR',{maximumFractionDigits:3});
 const person=id=>A.drivers[id]?.name||id,team=id=>A.teams[id]?.name||id;
 const date=value=>new Date(value+'T12:00:00Z').toLocaleDateString('fr-FR',{day:'numeric',month:'long',year:'numeric'});
 function teamStyle(id){
  const t=TEAMS_2026.find(t=>t.dbId===id||t.id===id)||HISTORIC_TEAMS.teams.find(t=>t.id===id);
  return `--archive-color:${t?.teamA||'#273e59'};--archive-light:${t?.teamB||'#8ba6c2'}`;
 }
 function link(label,kind,id){
  const exists=kind==='driver'?DRIVERS_2026.some(d=>d.dbId===id)||LEGENDS_F1.some(d=>d.dbId===id):TEAMS_2026.some(t=>t.dbId===id||t.id===id)||HISTORIC_TEAMS.teams.some(t=>t.id===id);
  return exists?`<button class="archive-link" data-kind="${kind}" data-entity="${esc(id)}">${esc(label)}</button>`:esc(label);
 }
 for(const year of Object.keys(A.seasons).map(Number).sort((a,b)=>b-a))yearSelect.add(new Option(year+(A.seasons[year].complete?'':' · en cours'),year));
 function drawStandings(s){
  const champions=[s.drivers.find(r=>r[4])||s.drivers.find(r=>r[0]==='1'),s.constructors.find(r=>r[4])||s.constructors.find(r=>r[0]==='1')];
  document.getElementById('archiveChampions').innerHTML=champions.map((r,i)=>{
   const id=r?.[1],label=i?'Constructeurs':'Pilotes',name=id?(i?team(id):person(id)):selectedYear<1958?'Championnat non créé':'Non renseigné';
   const flagCode=i?A.teams[id]?.flag:A.drivers[id]?.flag;
   return `<article class="archive-champion" style="${teamStyle(i?id:r?.[3]?.[0])}"><span>${s.complete?'Champion du monde':'En tête du classement'} · ${label}</span><h3>${flag(flagCode)} ${esc(name)}</h3><strong>${r?pts(r[2])+' points':selectedYear<1958?'Première édition en 1958':'—'}</strong></article>`;
  }).join('');
  document.getElementById('archiveDriversCount').textContent=s.drivers.length+' pilotes';
  document.getElementById('archiveDriverRows').innerHTML=s.drivers.map(r=>`<tr style="${teamStyle(r[3][0])}"><td>${esc(r[0])}</td><td><div class="archive-name">${flag(A.drivers[r[1]]?.flag)}${link(person(r[1]),'driver',r[1])}</div><small>${r[3].map(team).map(esc).join(' · ')||'Écurie non renseignée'}</small></td><td>${pts(r[2])}</td></tr>`).join('');
  document.getElementById('archiveTeamsCount').textContent=s.constructors.length?s.constructors.length+' lignes classées':'';
  document.getElementById('archiveConstructorRows').innerHTML=s.constructors.map(r=>`<tr style="${teamStyle(r[1])}"><td>${esc(r[0])}</td><td><div class="archive-name">${flag(A.teams[r[1]]?.flag)}${link(team(r[1]),'team',r[1])}</div>${r[3]?`<small>Moteur : ${esc(A.engines[r[3]]||r[3])}</small>`:''}</td><td>${pts(r[2])}</td></tr>`).join('');
  document.getElementById('archiveNoConstructors').hidden=selectedYear>=1958;
  document.getElementById('archiveConstructorTable').hidden=selectedYear<1958;
 }
 function drawRaces(s){
  const term=document.getElementById('archiveRaceSearch').value.trim().toLocaleLowerCase('fr');
  const races=s.races.filter(r=>[A.gps[r.gp],A.circuits[r.circuit]?.name,A.circuits[r.circuit]?.city,r.date].join(' ').toLocaleLowerCase('fr').includes(term));
  document.getElementById('archiveRaceCount').textContent=`${races.length} Grand${races.length>1?'s':''} Prix · ${s.races.filter(r=>r.finished).length} disputés`;
  const root=document.getElementById('archiveRaceList');root.replaceChildren();
  if(!races.length){root.innerHTML='<p class="archive-empty">Aucun Grand Prix ne correspond à cette recherche.</p>';return;}
  for(const r of races){
   const c=A.circuits[r.circuit]||{},rows=A.results[r.id]||[];
   const article=document.createElement('article');article.className='archive-race';
   article.innerHTML=`<div class="archive-race-head"><div class="archive-round">${String(r.round).padStart(2,'0')}</div><div><small>${date(r.date)}</small><h3>${flag(c.flag)} ${esc(A.gps[r.gp]||r.gp)}</h3><p>${esc(c.city||'')} · ${esc(c.name||'')}</p></div></div>${r.finished?`<div class="archive-podium">${[1,2,3].map(pos=>{
    const finishers=rows.filter(row=>row[1]===pos);
    return `<div class="archive-podium-place p${pos}"><span class="archive-medal">P${pos}</span>${finishers.length?finishers.map(row=>`<strong>${link(person(row[2]),'driver',row[2])}</strong><small>${esc(team(row[3]))}</small>`).join(''):'<strong>Place non attribuée</strong>'}${finishers.length>1?'<em>Voiture partagée</em>':''}</div>`;
   }).join('')}</div>${A.raceNotes?.[r.id]?`<p class="archive-race-note">${esc(A.raceNotes[r.id])}</p>`:''}<details class="archive-full-results"><summary>Voir tout le classement · ${rows.length} pilotes</summary><div class="archive-table-scroll"></div></details>`:'<p class="archive-empty">Résultats non encore disponibles dans les archives.</p>'}`;
   const details=article.querySelector('details');if(details)details.addEventListener('toggle',()=>{
    if(!details.open||details.dataset.loaded)return;details.dataset.loaded='true';
    details.querySelector('div').innerHTML=`<table class="archive-table"><thead><tr><th>Position</th><th>Pilote / écurie</th><th>Tours</th><th>Points</th></tr></thead><tbody>${rows.map(row=>`<tr style="${teamStyle(row[3])}"><td>${esc(row[0])}</td><td>${link(person(row[2]),'driver',row[2])}<small>${esc(team(row[3]))}${row[5]?' · voiture partagée':''}${row[6]?' · '+esc(row[6]):''}</small></td><td>${row[7]??'—'}</td><td>${pts(row[4])}</td></tr>`).join('')}</tbody></table>`;
   });root.appendChild(article);
  }
 }
 function draw(){
  const s=A.seasons[selectedYear];yearSelect.value=String(selectedYear);
  document.getElementById('archiveSelectedYear').textContent=selectedYear;
  document.getElementById('archiveStatus').textContent=s.complete?'Classements de fin de saison':`Saison en cours · classements après la manche ${s.round} · données au ${date(A.updated)}`;
  document.getElementById('archivePreviousYear').disabled=selectedYear===1950;document.getElementById('archiveNextYear').disabled=selectedYear===2026;
  document.getElementById('archiveStandingsPanel').hidden=tab!=='standings';document.getElementById('archiveRacesPanel').hidden=tab!=='races';
  document.querySelectorAll('[data-archive-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.archiveTab===tab);b.setAttribute('aria-selected',b.dataset.archiveTab===tab?'true':'false');});
  drawStandings(s);drawRaces(s);
 }
 window.openArchiveSeason=function(year,mode='standings'){if(!A.seasons[year])return;selectedYear=Number(year);tab=mode;document.getElementById('archiveRaceSearch').value='';showView('archives');draw();};
 yearSelect.addEventListener('change',()=>{selectedYear=Number(yearSelect.value);draw();});
 document.getElementById('archivePreviousYear').addEventListener('click',()=>{selectedYear--;draw();});
 document.getElementById('archiveNextYear').addEventListener('click',()=>{selectedYear++;draw();});
 document.getElementById('archiveRaceSearch').addEventListener('input',()=>drawRaces(A.seasons[selectedYear]));
 document.querySelectorAll('[data-archive-tab]').forEach(b=>b.addEventListener('click',()=>{tab=b.dataset.archiveTab;draw();}));
 document.getElementById('view-archives').addEventListener('click',e=>{
  const b=e.target.closest('[data-entity]');if(!b)return;const id=b.dataset.entity;
  if(b.dataset.kind==='driver'){
   const d=DRIVERS_2026.find(d=>d.dbId===id);if(d){showView('drivers');openDriverDetail(d.id);return;}
   const l=LEGENDS_F1.find(l=>l.dbId===id);if(l){showView('legends');openLegendDetail(l.id);}
  }else{
   const t=TEAMS_2026.find(t=>t.dbId===id||t.id===id);if(t){showView('teams');openTeamDetail(t.id);return;}
   if(HISTORIC_TEAMS.teams.some(t=>t.id===id)){showView('historic-teams');openHistoricTeamDetail(id);}
  }
 });
 draw();
})();

;
