/* qualifying.js */
(()=>{
 const snapshot=QUALIFYING_SNAPSHOT,select=document.getElementById('qualRace'),status=document.getElementById('qualStatus'),button=document.getElementById('qualRefresh');
 let calendar=snapshot.calendar,cache={},busy=false,sequence=0;
 cache[snapshot.latest.round]={race:snapshot.latest,at:snapshot.updated};
 try{const stored=JSON.parse(localStorage.getItem('f1-qualifying-v19'));if(stored&&stored.year===2026&&stored.results)cache={...cache,...stored.results};}catch{}
 const esc=escapeHtml;
 const start=r=>Date.parse((r.Qualifying?.date||r.date)+'T'+(r.Qualifying?.time||'00:00:00Z'));
 const format=v=>new Date(v).toLocaleString('fr-FR',{dateStyle:'medium',timeStyle:'short'});
 function options(){const old=select.value;select.replaceChildren(...calendar.map(r=>new Option(`${r.round} · ${r.raceName}`,r.round)));select.value=old||[...calendar].reverse().find(r=>start(r)<=Date.now())?.round||calendar[0].round;}
 function draw(message=''){
  const r=calendar.find(r=>r.round===select.value);if(!r)return;
  const entry=cache[r.round],rows=entry?.race?.QualifyingResults||[];
  document.getElementById('qualTitle').textContent=`Qualifications · ${r.raceName}`;
  status.textContent=message||(rows.length?`Résultats publiés · relevé du ${format(entry.at)}`:start(r)>Date.now()?`Prévues le ${format(start(r))}`:'En attente des résultats publiés');
  const winner=rows.find(x=>x.position==='1');
  document.getElementById('qualBody').innerHTML=rows.length?`<aside class="qual-pole"><span class="qual-pole-label">PREMIER DES QUALIFICATIONS</span><h3>${esc(winner?winner.Driver.givenName+' '+winner.Driver.familyName:'—')}</h3><p>${esc(winner?.Constructor?.name||'')}</p><strong>${esc(winner?.Q3||winner?.Q2||winner?.Q1||'—')}</strong></aside><div class="archive-table-scroll"><table class="archive-table qual-times"><thead><tr><th>Position</th><th>Pilote / écurie</th><th>Q1</th><th>Q2</th><th>Q3</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.position)}</td><td>${esc(x.Driver.givenName+' '+x.Driver.familyName)}<small>${esc(x.Constructor.name)}</small></td><td data-session="Q1">${esc(x.Q1||'—')}</td><td data-session="Q2">${esc(x.Q2||'—')}</td><td data-session="Q3">${esc(x.Q3||'—')}</td></tr>`).join('')}</tbody></table></div>`:`<p class="archive-empty">${start(r)>Date.now()?'Les qualifications n’ont pas encore eu lieu.':'Aucun classement publié pour cette séance. La phase Q1, Q2 ou Q3 en cours ne peut pas être confirmée.'} Vous pouvez choisir un autre Grand Prix pour consulter ses résultats.</p>`;
 }
 async function get(path){const res=await fetch('https://api.jolpi.ca/ergast/f1/2026/'+path,{signal:AbortSignal.timeout(15000)});if(!res.ok)throw Error(res.status);return (await res.json()).MRData.RaceTable.Races;}
 async function refresh(updateCalendar=false){
  if(busy)return;busy=true;button.disabled=true;const seq=++sequence,round=select.value;
  status.textContent='Actualisation…';
  try{
   if(updateCalendar){const data=await get('?limit=100');if(data.length){calendar=data;options();}}
   const races=await get(round+'/qualifying/?limit=100');
   if(races[0]?.QualifyingResults?.length&&races[0].round===round&&races[0].season==='2026'){
    cache[round]={race:races[0],at:new Date().toISOString()};
    try{localStorage.setItem('f1-qualifying-v19',JSON.stringify({year:2026,results:cache}));}catch{}
   }
   if(seq===sequence)draw();
  }catch{if(seq===sequence)draw(cache[select.value]?'Connexion indisponible · derniers résultats conservés':'Connexion indisponible · réessayez pour obtenir les résultats');}
  finally{busy=false;button.disabled=false;}
 }
 options();draw();refresh(true);
 select.addEventListener('change',()=>{sequence++;draw();if(!busy)refresh();else{const id=setInterval(()=>{if(!busy){clearInterval(id);refresh();}},200);}});
 button.addEventListener('click',()=>refresh(true));
 setInterval(()=>{if(!document.hidden&&document.getElementById('view-home').classList.contains('active'))refresh(true);},120000);
})();
